      en: ["The fourth highest peak in the world at 8,516 meters.", "First climbed on May 18, 1956, by a Swiss expedition.", "Connected to Mount Everest by the South Col at 7,906 m.", "Features three summits: Lhotse Main, Middle, and Shar.", "The South Face rises 3,200 meters in a near-vertical wall.", "Located in the Mahalangur range of the Himalayas."],
