      hu: ["Magasság: 7861 méter (Nuptse I csúcs)", "Helyszín: Mahalangur Himal, az Everest mellett", "Első megmászás: 1961. május 16. (Dennis Davis és Tashi serpa)", "Név jelentése: „Nyugati csúcs” tibeti nyelven", "Szerkezet: Egy hét különálló csúcsból álló hosszú gerinc", "Nehézség: Híres a technikailag nehéz déli faláról"],
      ro: ["Altitudine: 7861 metri (Vârful Nuptse I)", "Localizare: Masivul Mahalangur, lângă Everest și Lhotse", "Prima ascensiune: 16 mai 1961 de către o expediție britanică", "Semnificația numelui: „Vârful de Vest” în tibetană", "Geografie: Formează peretele sudic al văii Western Cwm", "Dificultate: Renumit pentru peretele sudic extrem de tehnic"],
      en: ["Elevation: 7,861 meters (25,791 feet) above sea level", "Location: Khumbu region, part of the Everest massif", "First Ascent: May 16, 1961, by a British-Nepalese team", "Name meaning: \"West Peak\" in Tibetan", "Ridge: Comprises seven distinct summits", "Climbing: Known for the extreme difficulty of its massive South Face"],
      es: ["El nombre significa 'pico del oeste' en tibetano.", "Una cresta larga con siete picos, no una sola montaña.", "El punto más alto es el Nuptse I con 7.861 metros.", "Situado a 2 km al suroeste del Monte Everest.", "Primer ascenso en 1961 por Dennis Davis y Tashi Sherpa.", "La pared del Nuptse es una enorme muralla de roca y hielo.", "Parte de la 'herradura' de Everest, Lhotse y Nuptse."],
      pt: ["O nome significa 'pico ocidental' em tibetano.", "Uma crista longa com sete picos, não uma única montanha.", "O ponto mais alto é o Nuptse I com 7.861 metros.", "Situado a 2 km a sudoeste do Monte Everest.", "Primeira ascensão em 1961 por Dennis Davis e Tashi Sherpa.", "A face do Nuptse é uma enorme parede de rocha e gelo.", "Parte da 'ferradura' de Everest, Lhotse e Nuptse."],
      fr: ["Le nom signifie « sommet de l'ouest » en tibétain.", "Une longue crête de sept sommets plutôt qu'une montagne isolée.", "Le point culminant est le Nuptse I à 7 861 mètres.", "Situé à 2 km au sud-ouest du mont Everest.", "Première ascension en 1961 par Dennis Davis et Tashi Sherpa.", "La face du Nuptse est une paroi colossale de roche et de glace.", "Fait partie du « fer à cheval » formé par l'Everest, le Lhotse et le Nuptse."],
