      hu: ["Magasság: 7227 méter a tengerszint felett", "Hegység: Langtang Himal, Közép-Nepál", "Első megmászás: 1978. október 24-én egy japán-nepáli csapat által", "Helyszín: Katmandutól 50 km-re északra", "Veszély: Rendkívül kitett a jéglavináknak", "Karakter: A Langtang-völgy legmagasabb és legdominánsabb csúcsa"],
      ro: ["Altitudine: 7227 metri deasupra nivelului mării", "Masiv: Langtang Himal, Nepalul central", "Prima ascensiune: 24 octombrie 1978 de către o echipă mixtă", "Localizare: Aproximativ 50 km nord de capitala Kathmandu", "Risc: Cunoscut pentru avalanșele de gheață catastrofale", "Poziție: Cel mai înalt vârf din regiunea sa"],
      en: ["Elevation: 7,227 meters (23,711 feet) above sea level", "Location: Langtang region, north-central Nepal", "First Ascent: October 24, 1978, via the East Ridge", "Relief: Rises over 3,000m above the adjacent valley", "History: Associated with the 2015 earthquake avalanche", "Rank: Highest peak in the Langtang Himal range"],
      es: ["Pico más alto del Langtang Himal (7.227 m).", "Gran relieve vertical sobre el valle de Langtang.", "Primera ascensión en 1978 por una expedición japonesa.", "Alto riesgo de avalanchas, evidenciado en el terremoto de 2015.", "Situado en el Parque Nacional de Langtang.", "La ruta de la cresta sureste es la vía de ascenso habitual.", "Un emblema de la región de senderismo de Langtang."],
      pt: ["Pico mais alto no Langtang Himal (7.227 m).", "Grande relevo vertical sobre o vale de Langtang.", "Primeira ascensão em 1960 por uma expedição japonesa.", "Alto risco de avalanches, como ficou claro no terramoto de 2015.", "Localizado no Parque Nacional de Langtang.", "A rota da aresta sudeste é o caminho de ascensão habitual.", "Um marco da região de trekking de Langtang."],
      fr: ["Plus haut sommet du Langtang Himal (7 227 m).", "Important dénivelé vertical au-dessus de la vallée du Langtang.", "Première ascension en 1978 par une expédition japonaise.", "Risque élevé d'avalanches, confirmé lors du séisme de 2015.", "Situé dans le parc national de Langtang.", "L'arête sud-est est la voie d'ascension habituelle.", "Sommet emblématique de la région de trek du Langtang."],
